"""Read one Houdini node help file and split it on headings.

The install keeps node help as wiki text in `$HFS/houdini/help/nodes.zip`.
One member is one node, for example `sop/box.txt`. This module opens that
member. It does not extract the archive and it does not start the help server.
"""

from __future__ import annotations

import os
import re
import zipfile
from dataclasses import dataclass

_HEADING = re.compile(r"^(=+)\s*(.+?)\s*\1\s*$")
_LABEL = re.compile(r"^(\s*)(\S.*):\s*$")
_CHANNELS = re.compile(r"^\s*#channels:\s*(.+)$")
_DIRECTIVE = re.compile(r"^\s*:")
_META = re.compile(r"^\s*#\w+:")

# Hou category name -> folder inside nodes.zip.
_FOLDERS = {
    "Sop": "sop",
    "Object": "obj",
    "Dop": "dop",
    "Vop": "vop",
    "Driver": "out",
    "Chop": "chop",
    "Shop": "shop",
    "Cop": "cop",
    "Cop2": "cop",
    "Copernicus": "cop",
    "Lop": "lop",
    "Top": "top",
    "Apex": "apex",
}

_CACHE: dict[tuple[str, str, int], "HelpFile"] = {}


@dataclass(frozen=True)
class Section:
    heading: str
    channels: tuple[str, ...]
    body: str

    def as_dict(self) -> dict:
        return {
            "heading": self.heading,
            "channels": list(self.channels),
            "body": self.body,
        }


@dataclass(frozen=True)
class HelpFile:
    source: str
    sections: tuple[Section, ...]


def parse_wiki(text: str) -> tuple[Section, ...]:
    """Split one wiki file.

    `= Title =` and `== Folder ==` are headings. After `@parameters`,
    `@inputs`, or `@outputs`, a `Label:` line at the parameter indent is a
    heading too. A more-indented `Label:` is a menu choice and stays in the
    parent section. `#channels:` holds the parameter's real names (`/sizex`).
    """
    sections: list[_Draft] = []
    current: _Draft | None = None
    param_indent: int | None = None
    in_parms = False

    def start(heading: str) -> _Draft:
        nonlocal current
        current = _Draft(heading)
        sections.append(current)
        return current

    for raw in text.splitlines():
        line = raw.replace("\t", "    ")
        stripped = line.strip()
        if not stripped:
            if current is not None:
                current.lines.append("")
            continue
        if stripped in {"@parameters", "@inputs", "@outputs"}:
            in_parms = True
            param_indent = None
            if stripped != "@parameters":
                start(stripped[1:].capitalize())
            continue
        if stripped.startswith("@related"):
            in_parms = False
            param_indent = None
            start("Related")
            continue
        heading = _HEADING.match(stripped)
        if heading and line.lstrip() == stripped:
            in_parms = in_parms and not stripped.startswith("=")
            param_indent = None
            start(heading.group(2).strip())
            continue
        label = _LABEL.match(line)
        if in_parms and label and not stripped.startswith("#") and not stripped.startswith(":"):
            indent = len(label.group(1))
            if param_indent is None or indent <= param_indent:
                param_indent = indent if param_indent is None else param_indent
                start(label.group(2).strip())
                continue
        if current is None:
            continue
        channels = _CHANNELS.match(line)
        if channels and not current.lines:
            names = tuple(part.strip() for part in channels.group(1).split() if part.strip())
            current.channels.extend(names)
            continue
        if _DIRECTIVE.match(line) or (_META.match(line) and not current.lines):
            continue
        current.lines.append(raw.rstrip())

    return tuple(_finish(item) for item in sections if item.heading)


def load_text(text: str, source: str) -> HelpFile:
    return HelpFile(source=source, sections=parse_wiki(text))


def load_path(path: str) -> HelpFile:
    key = (path, "", _mtime(path))
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    with open(path, encoding="utf-8", errors="replace") as handle:
        loaded = load_text(handle.read(), path)
    _CACHE[key] = loaded
    return loaded


def load_zip_member(zip_path: str, member: str) -> HelpFile:
    key = (zip_path, member, _mtime(zip_path))
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    with zipfile.ZipFile(zip_path) as archive:
        names = set(archive.namelist())
        chosen = member
        if chosen not in names:
            lowered = {name.lower(): name for name in names}
            chosen = lowered.get(member.lower().replace("\\", "/"), "")
        if not chosen:
            raise FileNotFoundError(member)
        text = archive.read(chosen).decode("utf-8", errors="replace")
    loaded = load_text(text, f"{zip_path}:{chosen}")
    _CACHE[key] = loaded
    return loaded


def member_for(category: str, internal: str) -> str:
    folder = _FOLDERS.get(category, category.lower())
    return f"{folder}/{internal}.txt"


def installed_help(category: str, internal: str, hfs: str | None = None) -> HelpFile:
    root = hfs or os.environ.get("HFS", "")
    if not root:
        raise FileNotFoundError("HFS is not set")
    help_root = os.path.join(root, "houdini", "help")
    member = member_for(category, internal)
    zip_path = os.path.join(help_root, "nodes.zip")
    if os.path.isfile(zip_path):
        try:
            return load_zip_member(zip_path, member)
        except FileNotFoundError:
            pass
    loose = os.path.join(help_root, "nodes", member.replace("/", os.sep))
    if os.path.isfile(loose):
        return load_path(loose)
    raise FileNotFoundError(member)


class _Draft:
    def __init__(self, heading: str) -> None:
        self.heading = heading
        self.channels: list[str] = []
        self.lines: list[str] = []


def _finish(draft: _Draft) -> Section:
    while draft.lines and draft.lines[-1] == "":
        draft.lines.pop()
    body = "\n".join(draft.lines).strip()
    return Section(draft.heading, tuple(draft.channels), body)


def _mtime(path: str) -> int:
    try:
        return int(os.path.getmtime(path))
    except OSError:
        return 0

"""Build the card from headings that are already in the file."""

from __future__ import annotations

import re

from houdini_wizard.help_file import Section


def card_from_heading(sections: list[dict], heading: str | None) -> dict:
    usable = [item for item in sections if item.get("heading")]
    names = [item["heading"] for item in usable]
    if heading and heading != "none":
        for item in usable:
            if item["heading"] == heading:
                return {
                    "kind": "quote",
                    "title": item["heading"],
                    "body": item.get("body") or "",
                    "headings": names,
                }
    return {
        "kind": "list",
        "title": "Headings in this file",
        "body": "",
        "headings": names,
    }


def match_parameter(sections: tuple[Section, ...] | list[Section], name: str, label: str) -> Section | None:
    name = name.strip().lstrip("/").lower()
    label = label.strip().lower()
    for section in sections:
        if label and section.heading.lower() == label:
            return section
        if name and _channel_match(section, name):
            return section
    return None


def match_error(sections: tuple[Section, ...] | list[Section], error_text: str) -> Section | None:
    text = error_text.strip().lower()
    if not text:
        return None
    best: Section | None = None
    best_len = 0
    for section in sections:
        tokens = [section.heading, *section.channels]
        for token in tokens:
            cleaned = token.strip().lstrip("/")
            if len(cleaned) < 3:
                continue
            if re.search(r"\b" + re.escape(cleaned.lower()) + r"\b", text):
                if len(cleaned) > best_len:
                    best = section
                    best_len = len(cleaned)
    return best


def _channel_match(section: Section, name: str) -> bool:
    for channel in section.channels:
        cleaned = channel.lstrip("/").lower()
        if cleaned == name:
            return True
    compact = re.sub(r"\s+", "", section.heading.lower())
    return compact == name

"""Decide the card. Gemma runs only when a cook error names no heading."""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from pathlib import Path

from houdini_wizard.card import card_from_heading, match_error, match_parameter
from houdini_wizard.help_file import Section

DEFAULT_MODEL = "gemma3:4b"
_NONE = "none"


def decide(sections: tuple[Section, ...] | list[Section], parm_name: str, parm_label: str, error_text: str) -> dict:
    """Return the workflow request. Exact matches set known_heading and skip Gemma."""
    payload = [section.as_dict() for section in sections]
    chosen = match_parameter(sections, parm_name, parm_label)
    if chosen is None and (parm_name or parm_label):
        chosen = None
    if chosen is None:
        chosen = match_error(sections, error_text) if not (parm_name or parm_label) else match_error(sections, error_text)
    # A selected parameter that does not match still falls through to the cook error.
    if parm_name or parm_label:
        chosen = match_parameter(sections, parm_name, parm_label)
        if chosen is None:
            chosen = match_error(sections, error_text)
    else:
        chosen = match_error(sections, error_text)
    needs_model = chosen is None and bool(error_text.strip())
    return {
        "sections": payload,
        "headings": [section.heading for section in sections],
        "error_text": error_text.strip(),
        "known_heading": chosen.heading if chosen is not None else "",
        "needs_model": needs_model,
    }


def finish(request: dict, heading: str | None = None) -> dict:
    chosen = heading if heading is not None else request.get("known_heading") or _NONE
    if request.get("needs_model") and heading is None:
        chosen = _NONE
    return card_from_heading(request["sections"], chosen)


def pick_heading(headings: list[str], error_text: str) -> str:
    """Ask local Gemma for one heading. The skill file is the system message."""
    if not headings:
        return _NONE
    schema = {
        "type": "object",
        "properties": {
            "heading": {"type": "string", "enum": [*headings, _NONE]},
        },
        "required": ["heading"],
    }
    user = "Headings:\n" + "\n".join(f"- {heading}" for heading in headings)
    user += "\n\nCook error:\n" + error_text.strip()
    payload = {
        "model": os.environ.get("HOUDINI_WIZARD_MODEL", DEFAULT_MODEL),
        "stream": False,
        "format": schema,
        "options": {"temperature": 0},
        "messages": [
            {"role": "system", "content": skill_text()},
            {"role": "user", "content": user},
        ],
    }
    url = os.environ.get("HOUDINI_WIZARD_OLLAMA", "http://127.0.0.1:11434").rstrip("/") + "/api/chat"
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(url, data=data, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            body = json.loads(response.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        raise RuntimeError(
            f"Ollama did not answer at {url}. Pull {payload['model']} and leave Ollama running."
        ) from exc
    content = body.get("message", {}).get("content", "")
    try:
        parsed = json.loads(content)
    except json.JSONDecodeError as exc:
        raise RuntimeError("Gemma did not return the heading JSON.") from exc
    heading = str(parsed.get("heading", _NONE)).strip()
    if heading not in headings:
        return _NONE
    return heading


def skill_text() -> str:
    override = os.environ.get("HOUDINI_WIZARD_SKILL")
    if override:
        return Path(override).read_text(encoding="utf-8")
    root = Path(__file__).resolve().parents[2]
    path = root / "skills" / "houdini-section" / "SKILL.md"
    if not path.is_file():
        raise FileNotFoundError(
            "skills/houdini-section/SKILL.md is missing. That file is the instruction Gemma receives."
        )
    return path.read_text(encoding="utf-8")

"""hython shelf. Reads the selection, stores the card, opens the dialog."""

from __future__ import annotations

import asyncio
import os

from houdini_wizard.help_file import installed_help
from houdini_wizard.pick import decide, finish, pick_heading
from houdini_wizard.workflow import connect, open_card, workflow_id


def show_card() -> None:
    import hou

    selected = _selection(hou)
    if selected is None:
        return
    node, parm_name, parm_label, error_text = selected
    try:
        category = node.type().category().name()
        internal = node.type().nameComponents()[2]
        hfs = hou.getenv("HFS") or os.environ.get("HFS", "")
        help_file = installed_help(category, internal, hfs)
    except FileNotFoundError as exc:
        hou.ui.displayMessage(
            f"This install has no help file for the node.\n{exc}",
            title="Houdini wizard",
            severity=hou.severityType.Warning,
        )
        return
    request = decide(help_file.sections, parm_name, parm_label, error_text)
    card_id = workflow_id(node.path(), parm_name or parm_label, error_text)
    card, note = _store(card_id, request)
    _present(hou, card, note)


def _selection(hou):
    nodes = list(hou.selectedNodes())
    parm = _selected_parm(hou, nodes[0] if nodes else None)
    node = parm.node() if parm is not None else (nodes[0] if nodes else None)
    if node is None:
        if hasattr(hou, "ui"):
            hou.ui.displayMessage("Select a node, then click the shelf.", title="Houdini wizard")
        return None
    parm_name = parm.name() if parm is not None else ""
    parm_label = ""
    if parm is not None:
        parm_label = parm.description() or parm.parmTemplate().label()
    return node, parm_name, parm_label, node.errors() or ""


def _selected_parm(hou, node):
    """The parameter whose channel is selected on this node, if Houdini has one."""
    if node is None or not hasattr(hou, "ui"):
        return None
    try:
        editors = [tab for tab in hou.ui.paneTabs() if tab.type() == hou.paneTabType.ChannelEditor]
    except Exception:
        return None
    for editor in editors:
        channel_list = getattr(editor, "channelList", None)
        if not callable(channel_list):
            continue
        try:
            selected = channel_list().selected()
        except Exception:
            continue
        for parm in selected:
            try:
                if parm.node().path() == node.path():
                    return parm
            except Exception:
                continue
    return None


def _store(card_id: str, request: dict) -> tuple[dict, str]:
    try:
        card = asyncio.run(_open(card_id, request))
        return card, ""
    except Exception as exc:
        note = f"Temporal did not keep this card ({exc}). The quote is still from the help file."
        heading = request.get("known_heading") or ""
        if request.get("needs_model"):
            try:
                heading = pick_heading(request["headings"], request["error_text"])
                note = "Temporal did not keep this card. Gemma still chose the heading."
            except Exception as model_exc:
                heading = "none"
                note = f"Temporal and Gemma did not run ({model_exc}). Open a heading from the file."
        return finish(request, heading), note


async def _open(card_id: str, request: dict) -> dict:
    client = await connect()
    return await open_card(client, card_id, request)


def _present(hou, card: dict, note: str) -> None:
    if card["kind"] == "list":
        labels = card["headings"]
        if not labels:
            hou.ui.displayMessage("This help file has no headings.", title="Houdini wizard")
            return
        picks = hou.ui.selectFromList(
            labels,
            exclusive=True,
            title="Houdini wizard",
            message="No heading matched. Open one from this file.",
        )
        if not picks:
            return
        heading = labels[picks[0]]
        for item in _sections_from_card(card, heading):
            _show_quote(hou, item["heading"], item.get("body") or "", note)
            return
        return
    _show_quote(hou, card["title"], card["body"], note)


def _sections_from_card(card: dict, heading: str) -> list[dict]:
    # The list card does not repeat bodies. The caller passes headings only.
    # Shelf keeps the request sections on the card headings and re-reads via title match
    # through the headings stored beside the dialog. Bodies travel in card when quoted.
    return [{"heading": heading, "body": ""}]


def _show_quote(hou, title: str, body: str, note: str) -> None:
    text = body or "This heading has no text in the installed file."
    if note:
        text = f"{text}\n\n{note}"
    hou.ui.displayMessage(text, title=title, severity=hou.severityType.Message)

